import time
# handling common functionality of iperf endpoint
from moler.helpers import instance_id
from . import host


class IperfEndpoint:
    """Managing one side of iperf data transfer."""
    def __init__(self, name, dt_definition, configuration, cmd_options):
        """
        Basic initialization.

        :param name: name assigned to DataTransfer object
        :param dt_definition: DataTransferDefinition object - definition of data transfer characteristics
        :param configuration: configuration
        :param cmd_options: CmdOptions instance
        :param logger: logger to use
        """
        self._name = name
        self._dt_definition = dt_definition
        self._configuration = configuration
        self._cmd_options = cmd_options
        self.iperf_cmd = None  # moler iperf command object (either client or server)

    @property
    def config_version(self):
        """Which versions of config format we have"""
        ver = self._configuration.get('VERSION', 1.0)
        return ver

    def register_timeout_adjuster(self):
        """Register callback that will adjust iperf_cmd timeout"""
        iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_cmd)
        iperf_cmd.subscribe(self._timeout_adjuster)

    def _timeout_adjuster(self, from_client, to_server, data_record=None, report=None):
        iperf_start_duration = time.time() - self._cmd_options.interval - self.iperf_cmd.start_time
        recalculated_timeout = self._recalculate_timeout(self.iperf_cmd)
        if recalculated_timeout > self.iperf_cmd.timeout:
            self._log_cmd_start(self.iperf_cmd, iperf_start_duration, recalculated_timeout)
            self.iperf_cmd.timeout = recalculated_timeout
        iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_cmd)
        iperf_cmd.unsubscribe(self._timeout_adjuster)
        iperf_cmd.subscribe(self._cmd_report_reporter)

    def _cmd_report_reporter(self, from_client, to_server, data_record=None, report=None):
        if report:
            self._log_cmd_report(self.iperf_cmd, report)
            iperf_cmd = host.retrieve_real_iperf_command_object(self.iperf_cmd)
            iperf_cmd.unsubscribe(self._cmd_report_reporter)

    def _recalculate_timeout(self, iperf_command):
        # iperf startup may be delayed
        # so, we recalculate iperf timeout to be behind iperf duration
        recalculated_start_time = time.time() - self._cmd_options.interval  # we are at first report after first interval
        estimated_end_time = recalculated_start_time + self._cmd_options.duration
        recalculated_timeout = (estimated_end_time - iperf_command.start_time) + 2.0
        return recalculated_timeout

    @staticmethod
    def _cmd_short_dump(cmd):
        dump = f'{cmd.__class__.__name__}(id:{instance_id(cmd)})'
        return dump

    @staticmethod
    def _cmd_timing_dump(cmd, need_timeout=False):
        cmd_str = IperfEndpoint._cmd_short_dump(cmd)
        timeout = cmd.timeout
        passed = time.time() - cmd.start_time
        remaining = timeout - passed
        progress = f'remaining {remaining:.3f} [sec], already passed {passed:.3f} [sec]'
        if need_timeout:
            dump = f'{cmd_str} {progress}, timeout {timeout:.3f} [sec]'
        else:
            dump = f'{cmd_str} {progress}'
        return dump

    @staticmethod
    def _log_into_connection_log(cmd, msg):
        iperf_cmd = host.retrieve_real_iperf_command_object(cmd)
        iperf_cmd.connection.data_logger.info(msg)

    @staticmethod
    def _log_cmd_start(cmd, start_duration, recalculated_timeout):
        cmd_dump = IperfEndpoint._cmd_short_dump(cmd)
        timeout = cmd.timeout
        msg = f'{cmd_dump} start_duration: {start_duration:.3f}, timeout: {timeout} new_timeout: {recalculated_timeout:.3f} [sec]'
        IperfEndpoint._log_into_connection_log(cmd, msg)

    @staticmethod
    def _log_cmd_report(cmd, report):
        cmd_dump = IperfEndpoint._cmd_timing_dump(cmd, need_timeout=True)
        msg = f'{cmd_dump}; report: {report}'
        IperfEndpoint._log_into_connection_log(cmd, msg)
